(()=>{
'use strict';if(window.__gtavCommunityProfileLoaded)return;window.__gtavCommunityProfileLoaded=true;
const API='/api/profile',reduce=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const AVATARS=[['generic','Default profile'],['gas-mask','Gas mask'],['trevor','Trevor'],['franklin','Franklin'],['michael','Michael'],['robber','Masked robber']];
const AVATAR_IMAGES={generic:'/assets/avatars/generic.jpg','gas-mask':'/assets/avatars/gas-mask.jpg',trevor:'/assets/avatars/trevor.jpg',franklin:'/assets/avatars/franklin.jpg',michael:'/assets/avatars/michael.jpg',robber:'/assets/avatars/robber.jpg'};
const normalizeAvatar=id=>AVATAR_IMAGES[id]?id:'generic';
let profile=undefined,resolveReady;const ready=new Promise(r=>resolveReady=r);let selected='generic',checkTimer=0,drag=null,pickerTimer=0;
const request=async(url,options={})=>{const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options});let data={};try{data=await r.json()}catch{}if(!r.ok){const e=new Error(data.message||data.error||'Request failed');e.code=data.error;e.status=r.status;throw e}return data};
const person=`<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4.5 21a7.5 7.5 0 0 1 15 0"/></svg>`;
const closeSvg=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><path d="m7 7 10 10M17 7 7 17"/></svg>`;
const pencilSvg=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 20h4l10.5-10.5a2.3 2.3 0 0 0-4-4L4 16v4Z"/><path d="m13.5 6.5 4 4"/></svg>`;
function avatarArt(id){id=normalizeAvatar(id);const art=document.createElement('span');art.className=`profile-avatar-art avatar-${id}`;const img=document.createElement('img');img.alt='';img.src=AVATAR_IMAGES[id];img.loading='eager';img.decoding='async';art.append(img);return art}
function setArt(container,id){container.replaceChildren(avatarArt(normalizeAvatar(id)))}
function build(){
 const trigger=document.createElement('button');trigger.type='button';trigger.className='profile-trigger';trigger.setAttribute('aria-label','Open community profile');trigger.innerHTML=person+'<span class="profile-trigger-avatar" aria-hidden="true"></span>';
 const actions=document.querySelector('.header-actions'),menu=actions?.querySelector('.menu-toggle');if(actions)actions.insertBefore(trigger,actions.querySelector('.settings-trigger')||menu||null);
 const backdrop=document.createElement('div');backdrop.className='profile-backdrop';backdrop.hidden=true;
 const sheet=document.createElement('section');sheet.className='profile-sheet';sheet.setAttribute('role','dialog');sheet.setAttribute('aria-modal','true');sheet.setAttribute('aria-labelledby','profile-title');sheet.setAttribute('aria-hidden','true');sheet.innerHTML=`<span class="profile-grip" aria-hidden="true"></span><div class="profile-head"><div class="profile-head-copy"><small>COMMUNITY ID</small><strong>Profile</strong></div><button type="button" class="profile-close" aria-label="Close profile">${closeSvg}</button></div><svg class="profile-sheet-edge" aria-hidden="true" focusable="false"><path pathLength="1000"></path></svg><div class="profile-body"><p class="profile-required-note" role="status"></p><div class="profile-hero"><button type="button" class="profile-avatar-edit" aria-label="Change avatar"><span class="profile-avatar-large"></span><span class="profile-avatar-pencil" aria-hidden="true">${pencilSvg}</span></button><h2 id="profile-title">Get your ID</h2><p class="profile-hero-copy">Choose a unique display name. No email or password is required.</p><span class="profile-status-pill" hidden>Community ID active</span></div><div class="profile-avatar-picker" hidden><div class="profile-avatar-picker-head"><span>Choose avatar</span><button type="button" class="profile-avatar-picker-done">Done</button></div><div class="profile-avatar-strip" role="group" aria-label="Choose an avatar"></div></div><form class="profile-form" novalidate><label class="profile-field"><span>Display name <small>3–24 characters · unique</small></span><div class="profile-name-wrap"><input name="displayName" maxlength="24" minlength="3" autocomplete="off" autocapitalize="words" spellcheck="false" placeholder="Choose a display name"><span class="profile-name-state">Required</span></div></label><div class="profile-actions"><p class="profile-note">This ID stays on this browser. If browser data is erased, the ID cannot be recovered.</p><button class="profile-save" type="submit" disabled>Get your ID</button></div><p class="profile-message" role="status" aria-live="polite"></p></form></div>`;
 document.body.append(backdrop,sheet);const strip=sheet.querySelector('.profile-avatar-strip');for(const [id,label]of AVATARS){const b=document.createElement('button');b.type='button';b.className='profile-avatar-choice';b.dataset.avatar=id;b.setAttribute('aria-label',label);b.setAttribute('aria-pressed','false');b.append(avatarArt(id));strip.append(b)}
 const edge=sheet.querySelector('.profile-sheet-edge'),path=edge.querySelector('path');const fitEdge=()=>{const w=sheet.clientWidth,h=sheet.clientHeight;if(!w||!h)return;const r=Math.min(parseFloat(getComputedStyle(sheet).borderTopLeftRadius)||0,w/2);edge.setAttribute('viewBox',`0 0 ${w} ${h}`);path.setAttribute('d',`M1 ${r+1} Q1 1 ${r+1} 1 H${w-r-1} Q${w-1} 1 ${w-1} ${r+1} V${h-1} H1 Z`)};new ResizeObserver(fitEdge).observe(sheet);requestAnimationFrame(fitEdge);
 return {trigger,backdrop,sheet,form:sheet.querySelector('.profile-form'),input:sheet.querySelector('input[name="displayName"]'),state:sheet.querySelector('.profile-name-state'),save:sheet.querySelector('.profile-save'),message:sheet.querySelector('.profile-message'),heroAvatar:sheet.querySelector('.profile-avatar-large'),avatarEdit:sheet.querySelector('.profile-avatar-edit'),picker:sheet.querySelector('.profile-avatar-picker'),pickerDone:sheet.querySelector('.profile-avatar-picker-done'),heroTitle:sheet.querySelector('#profile-title'),heroCopy:sheet.querySelector('.profile-hero-copy'),active:sheet.querySelector('.profile-status-pill'),required:sheet.querySelector('.profile-required-note'),strip,close:sheet.querySelector('.profile-close'),head:sheet.querySelector('.profile-head'),grip:sheet.querySelector('.profile-grip')}
}
let ui;
function syncAvatar(){selected=normalizeAvatar(selected);ui.strip.querySelectorAll('.profile-avatar-choice').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.avatar===selected)));setArt(ui.heroAvatar,selected);if(profile)setArt(ui.trigger.querySelector('.profile-trigger-avatar'),normalizeAvatar(profile.avatar));}
function validLocal(value){const n=value.trim().replace(/\s+/g,' ');return n.length>=3&&n.length<=24&&/^[\p{L}\p{N}._ -]+$/u.test(n)}
function sync(){if(!ui)return;const has=!!profile;ui.trigger.classList.toggle('has-profile',has);if(profile)profile.avatar=normalizeAvatar(profile.avatar);selected=profile?.avatar||selected||'generic';ui.input.value=profile?.displayName||ui.input.value||'';ui.heroTitle.textContent=has?profile.displayName:'Get your ID';ui.heroCopy.textContent=has?'Manage your display name and avatar.':'Choose a unique display name. No email or password is required.';ui.active.hidden=!has;ui.save.textContent=has?'Save changes':'Get your ID';ui.state.textContent=has?'Current name':'Required';ui.state.className='profile-name-state';ui.message.textContent='';ui.message.className='profile-message';syncAvatar();validateButton()}
function validateButton(){const v=ui.input.value.trim();ui.save.disabled=!validLocal(v)||ui.state.classList.contains('taken')}
function reasonText(reason){if(reason==='franklin')return'Community ID required for Franklin.';if(reason==='feedback')return'Community ID required to send feedback.';return''}
function showPicker(){clearTimeout(pickerTimer);ui.picker.hidden=false;requestAnimationFrame(()=>ui.picker.classList.add('is-open'));ui.avatarEdit.setAttribute('aria-expanded','true');window.gtavHaptics?.trigger?.('selection')}
function hidePicker(){ui.picker.classList.remove('is-open');ui.avatarEdit.setAttribute('aria-expanded','false');pickerTimer=setTimeout(()=>{if(!ui.picker.classList.contains('is-open'))ui.picker.hidden=true},reduce()?0:180)}
function open(reason=''){hidePicker();ui.sheet.dataset.required=String(!!reason);ui.required.textContent=reasonText(reason);ui.backdrop.hidden=false;requestAnimationFrame(()=>{ui.backdrop.classList.add('is-open');ui.sheet.classList.add('is-open')});ui.sheet.setAttribute('aria-hidden','false');document.body.classList.add('profile-open');setTimeout(()=>ui.input.focus({preventScroll:true}),reduce()?0:280);window.gtavHaptics?.trigger?.('open')}
function close(){hidePicker();ui.sheet.classList.remove('is-open');ui.backdrop.classList.remove('is-open');ui.sheet.style.transform='';ui.sheet.setAttribute('aria-hidden','true');document.body.classList.remove('profile-open');setTimeout(()=>{ui.backdrop.hidden=true;ui.trigger.focus({preventScroll:true})},reduce()?0:320);window.gtavHaptics?.trigger?.('close')}
async function checkName(){clearTimeout(checkTimer);const value=ui.input.value.trim();ui.state.className='profile-name-state';if(!validLocal(value)){ui.state.textContent=value?'Use 3–24 characters':'Required';validateButton();return}if(profile&&value.toLocaleLowerCase()===profile.displayName.toLocaleLowerCase()){ui.state.textContent='Current name';ui.state.classList.add('available');validateButton();return}ui.state.textContent='Checking…';checkTimer=setTimeout(async()=>{try{const data=await request(`${API}?check=${encodeURIComponent(value)}`);ui.state.textContent=data.available?'Available':'Already taken';ui.state.className='profile-name-state '+(data.available?'available':'taken')}catch{ui.state.textContent='Check unavailable';ui.state.className='profile-name-state'}validateButton()},320)}
async function save(event){event.preventDefault();const displayName=ui.input.value.trim().replace(/\s+/g,' ');if(!validLocal(displayName)||ui.state.classList.contains('taken'))return;ui.save.disabled=true;ui.message.textContent=profile?'Saving changes…':'Creating your ID…';ui.message.className='profile-message';try{const data=await request(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:profile?'update':'claim',displayName,avatar:normalizeAvatar(selected)})});profile=data.profile;sync();ui.message.textContent=profile?'Community ID ready.':'';window.dispatchEvent(new CustomEvent('gtav:identity-changed',{detail:{profile}}));window.gtavHaptics?.trigger?.('success');setTimeout(close,650)}catch(e){ui.message.textContent=e.message||'Could not save your Community ID.';ui.message.className='profile-message error';if(e.code==='display_name_taken'){ui.state.textContent='Already taken';ui.state.className='profile-name-state taken'}validateButton();window.gtavHaptics?.trigger?.('warning')}}
async function refresh(){try{const data=await request(API);profile=data.profile||null}catch{profile=null}sync();return profile}
function bindDrag(surface){surface.style.touchAction='none';surface.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button,input'))return;drag={id:e.pointerId,y:e.clientY};ui.sheet.classList.add('is-dragging');surface.setPointerCapture(e.pointerId)});surface.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dy=Math.max(0,e.clientY-drag.y);ui.sheet.style.transform=`translate(-50%,${Math.min(dy,ui.sheet.clientHeight)}px)`});const finish=(e,cancelled)=>{if(!drag||drag.id!==e.pointerId)return;const dy=e.clientY-drag.y;drag=null;ui.sheet.classList.remove('is-dragging');ui.sheet.style.transform='';if(!cancelled&&dy>72)close()};surface.addEventListener('pointerup',e=>finish(e,false));surface.addEventListener('pointercancel',e=>finish(e,true))}
function intercept(){document.addEventListener('click',async e=>{if(!(e.target instanceof Element))return;const launcher=e.target.closest('.ask-franklin-launcher');if(!launcher)return;if(profile)return;e.preventDefault();e.stopImmediatePropagation();await ready;if(profile){launcher.click();return}open('franklin')},true);document.addEventListener('pointerdown',e=>{if(!(e.target instanceof Element)||!e.target.closest('#feedback-hold')||profile)return;e.preventDefault();e.stopImmediatePropagation();open('feedback')},true);document.addEventListener('keydown',e=>{if(!e.target?.closest?.('#feedback-hold')||profile||![' ','Enter'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();open('feedback')},true)}
function start(){ui=build();ui.avatarEdit.setAttribute('aria-expanded','false');ui.trigger.addEventListener('click',()=>open());ui.close.addEventListener('click',close);ui.backdrop.addEventListener('click',close);ui.form.addEventListener('submit',save);ui.input.addEventListener('input',()=>{checkName();validateButton()});ui.avatarEdit.addEventListener('click',()=>ui.picker.hidden||!ui.picker.classList.contains('is-open')?showPicker():hidePicker());ui.pickerDone.addEventListener('click',hidePicker);ui.strip.addEventListener('click',e=>{const b=e.target.closest('.profile-avatar-choice');if(!b)return;selected=normalizeAvatar(b.dataset.avatar);syncAvatar();validateButton();window.gtavHaptics?.trigger?.('selection')});bindDrag(ui.grip);bindDrag(ui.head);intercept();refresh().finally(resolveReady);window.gtavIdentity={get:()=>profile,ready,open,close,refresh,require:async reason=>{await ready;if(profile)return true;open(reason);return false}}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
